mapper.insert:
INSERT INTO overtime_request (
    employee_id, work_date, start_time, end_time, reason, approval_status
) VALUES (
             #{employeeId}, #{workDate}, #{startTime}, #{endTime}, #{reason}, #{approvalStatus}
         )

mapper.update:
UPDATE overtime_request
SET approval_status = #{approvalStatus},
    reject_reason = #{rejectReason}
WHERE overtime_id = #{overtimeId}
  AND approval_status = 'PENDING'

mapper.select:
SELECT overtime_id as overtimeId, employee_id as employeeId, work_date as workDate, start_time as startTime, end_time as endTime, reason as reason, approval_status as approvalStatus, reject_reason as rejectReason FROM overtime_request
approval_status = #{approvalStatus}
ORDER BY start_time DESC
